INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1136414', 'Battle of Havana', 'The Battle of Havana was fought between 12–14 October 1748 off Havana between the British and Spanish navies during the War of Jenkins'' Ear. A British squadron under Rear-Admiral of the Red Charles Knowles attacked a Spanish squadron led by Lieutenant-general Andrés Reggio during an attempt by Knowles to intercept the Spanish treasure fleet.', 1748, 10, 12, NULL, NULL, NULL, 'day', '12 October 1748', 43, 'https://en.wikipedia.org/wiki/Battle_of_Havana_(1748)'),
  ('Q562277', 'Battle of Havana', 'The siege of Havana was the capture of the Spanish-held city of Havana, Cuba in 1762 as part of the war between Britain and Spain which formed part of the larger Seven Years'' War. After the Spanish abandoned their former policy of neutrality by signing the family compact with France, Britain declared war on Spain in January 1762.', 1762, 6, 6, 1762, 8, 13, 'day', '6 June 1762 – 13 August 1762', 52, 'https://en.wikipedia.org/wiki/Siege_of_Havana'),
  ('Q616846', 'Anglo-Spanish War', 'The Anglo-Spanish War (Spanish: Guerra Anglo-Española) was fought between Britain and Spain as part of the Seven Years'' War. It lasted from January 1762 until February 1763, when the Treaty of Paris brought it to an end.', 1762, NULL, NULL, 1763, NULL, NULL, 'year', '1762–1763', 47, 'https://en.wikipedia.org/wiki/Anglo-Spanish_War_(1762%E2%80%931763)'),
  ('Q184637', 'Ten Years'' War', 'The Ten Years'' War (Spanish: Guerra de los Diez Años; 1868–1878), also known as the Great War (Guerra Grande) and the War of ''68, was a war of independence of Cuba from Spain. The uprising was led by Cuban-born planters and other wealthy natives.', 1868, 10, 10, 1878, NULL, NULL, 'day', '10 October 1868 – 1878', 65, 'https://en.wikipedia.org/wiki/Ten_Years''_War'),
  ('Q1529375', 'Battle of Havana', 'The Battle of Havana on 9 November 1870 was an indecisive single ship action between the German gunboat Meteor and the French aviso Bouvet off the coast of Havana, Cuba during the Franco-Prussian War. The battle was the only naval engagement of the war, and showed the inability of either navy to gain a decisive advantage over the other.', 1870, 11, 9, NULL, NULL, NULL, 'day', '9 November 1870', 43, 'https://en.wikipedia.org/wiki/Battle_of_Havana_(1870)'),
  ('Q1514908', 'Cuban War of Independence', 'The Cuban War of Independence, fought from 1895 to 1898, was the last of three liberation wars that Cuba fought against Spain, following the Ten Years'' War (1868–1878) and the Little War (1879–1880). Throughout the course of the war, Spain sent 220,285 soldiers to Cuba, the largest army to cross the Atlantic until World War II, according to the Library of Congress.', 1895, 2, 24, 1898, NULL, NULL, 'day', '24 February 1895 – 1898', 69, 'https://en.wikipedia.org/wiki/Cuban_War_of_Independence'),
  ('Q2888446', 'Battle of Dos Ríos', 'The Battle of Dos Ríos was fought in Cuba during its war of independence from Spain. It was a rearguard action fought by the Cuban Liberation Army against Spanish forces, which allowed the rebels to escape to the west of the island.', 1895, 5, 19, NULL, NULL, NULL, 'day', '19 May 1895', 39, 'https://en.wikipedia.org/wiki/Battle_of_Dos_R%C3%ADos'),
  ('Q2889200', 'Battle of Mal Tiempo', 'The Battle of Mal Tiempo was a battle of the Cuban War of Independence that took place on December 15, 1895, a few kilometers away from Cruces, Cienfuegos Province. In the battle, Mambises and Spanish forces faced each other, the former being victorious.', 1895, 12, 15, NULL, NULL, NULL, 'day', '15 December 1895', 39, 'https://en.wikipedia.org/wiki/Battle_of_Mal_Tiempo'),
  ('Q5778586', 'Battle of Calimete', 'The Battle of Calimete was a battle of the Cuban War of Independence on December 29, 1895, which was led by Cuban independence activists Máximo Gómez, Antonio Maceo and later on, Serafín Sánchez.', 1895, 12, 29, NULL, NULL, NULL, 'day', '29 December 1895', 34, 'https://en.wikipedia.org/wiki/Battle_of_Calimete'),
  ('Q55495734', 'Batalla de Coliseo', 'The Battle of Coliseo was a group of military actions carried out in the surroundings of the town of the same name, Matanzas Province, Cuba on December 23, 1895 during the Cuban War of Independence.', 1895, 12, 23, NULL, NULL, NULL, 'day', '23 December 1895', 34, 'https://en.wikipedia.org/wiki/Battle_of_Coliseo'),
  ('Q5722624', 'Battle of Las Taironas', 'The Battle of Las Taironas was a battle of the Cuban War of Independence that took place on January 17, 1896 at Pinar del Río between Cuban forces led by Major General Antonio Maceo and the Spanish led by lieutenant colonel Ulpiano Sanchez Echevarria who was a Cuban native.', 1896, 1, 17, NULL, NULL, NULL, 'day', '17 January 1896', 34, 'https://en.wikipedia.org/wiki/Battle_of_Las_Taironas'),
  ('Q55460370', 'Batalla de Loma del Gato', 'The Battle of Loma del Gato took place during the Cuban War of Independence on July 5, 1896 at Santiago de Cuba, Oriente Province. It is notable for the death of Mambí General José Maceo.', 1896, 7, 5, NULL, NULL, NULL, 'day', '5 July 1896', 34, 'https://en.wikipedia.org/wiki/Battle_of_Loma_del_Gato'),
  ('Q1215310', 'Battle of San Juan Hill', 'The Battle of San Juan Hill (Spanish: Batalla de las Colinas de San Juan), also known as the Battle for the San Juan Heights, was a major battle of the Spanish–American War fought July 1, 1898, between an American force under the command of William Rufus Shafter and Joseph Wheeler against a Spanish force led by Arsenio Linares y Pombo. The combined assaults on Kettle Hill and San Juan Hill that together form San Juan Heights proved to be one of the most significant battles of the war and, along with the Siege of Santiago, a decisive battle in deciding the fate of the United States Army…', 1898, 7, 1, NULL, NULL, NULL, 'day', '1 July 1898', 45, 'https://en.wikipedia.org/wiki/Battle_of_San_Juan_Hill'),
  ('Q1999889', 'Battle of Santiago de Cuba', 'The Battle of Santiago de Cuba was fought on July 3, 1898, between a United States Navy squadron led by Rear Admiral William T. Sampson and Commodore Winfield Scott Schley and a Spanish Navy squadron under Counter-admiral Pascual Cervera y Topete during the Spanish–American War. The significantly more powerful American squadron, comprising four battleships and two armored cruisers, decisively defeated the outgunned Spanish squadron, which consisted of four armored cruisers and two destroyers, sinking all of Cervera''s ships while losing none of their own.', 1898, 7, 3, NULL, NULL, NULL, 'day', '3 July 1898', 52, 'https://en.wikipedia.org/wiki/Battle_of_Santiago_de_Cuba'),
  ('Q2887938', 'Battle of El Caney', 'The Battle of El Caney was fought on July 1, 1898, during the Spanish-American War. 600 Spanish soldiers held for twelve hours, until they ran out of ammunition, against Henry W. Lawton''s 5th US Division, made up of 6,899 men.', 1898, 7, 1, NULL, NULL, NULL, 'day', '1 July 1898', 41, 'https://en.wikipedia.org/wiki/Battle_of_El_Caney'),
  ('Q2889110', 'Battle of Las Guásimas', 'The Battle of Las Guásimas of June 24, 1898 was a Spanish rearguard action by Major General Antero Rubín against advancing columns led by Major General "Fighting Joe" Wheeler and the first land engagement of the Spanish–American War. The battle unfolded from Wheeler''s attempt to storm Spanish positions at Las Guásimas de Sevilla, in the jungles surrounding Santiago de Cuba, with the 1st U.S. Volunteer Cavalry and the 10th Regular Cavalry.', 1898, 6, 24, NULL, NULL, NULL, 'day', '24 June 1898', 39, 'https://en.wikipedia.org/wiki/Battle_of_Las_Gu%C3%A1simas'),
  ('Q4871158', 'Battle of Guantánamo Bay', 'The Battle of Guantánamo Bay was fought from June 6 to June 14, 1898, during the Spanish–American War, when American and Cuban forces seized the strategically and commercially important harbor of Guantánamo Bay, Cuba. Capturing the bay from the Spanish forces was instrumental in the following Battle of Santiago de Cuba and the subsequent invasion of Puerto Rico.', 1898, 6, 6, 1898, 6, 10, 'day', '6 June 1898 – 10 June 1898', 34, 'https://en.wikipedia.org/wiki/Battle_of_Guant%C3%A1namo_Bay'),
  ('Q7510374', 'Siege of Santiago', 'The siege of Santiago, also known as the siege of Santiago de Cuba, was the last major operation of the Spanish–American War on the island of Cuba.', 1898, NULL, NULL, 1898, 7, 17, 'year', '1898', 39, 'https://en.wikipedia.org/wiki/Siege_of_Santiago'),
  ('Q2029196', 'War of 1912', 'The War of 1912 (Spanish: Levantamiento Armado de los Independientes de Color, lit. ''Armed Uprising of the Independents of Color''), also known as the Little Race War or The Twelve, was a series of protests and uprisings in 1912 in Cuba. The conflict was between Afro-Cuban rebels and the armed forces of Cuba, taking place mainly in the eastern region of the island where most Afro-Cubans lived and worked.', 1912, NULL, NULL, NULL, NULL, NULL, 'year', '1912', 37, 'https://en.wikipedia.org/wiki/War_of_1912'),
  ('Q16983546', 'Hay-Quesada Treaty', 'The Hay–Quesada Treaty is the agreement reached between the governments of Cuba and the United States, which was negotiated in 1904, but not ratified by both parties until 1925. By the terms of this treaty the U.S. recognized Cuban sovereignty over the territory of the Isle of Pines off the southern coast of the island of Cuba, which since 1978 has been known as Isla de la Juventud (Isle of Youth).', 1925, NULL, NULL, NULL, NULL, NULL, 'year', '1925', 26, 'https://en.wikipedia.org/wiki/Hay%E2%80%93Quesada_Treaty'),
  ('Q5492732', 'Cuban coup d''etat of 1933', 'The Cuban Revolution of 1933 (Spanish: Revolución cubana de 1933), also called the Sergeants'' Revolt, was a coup d''etat that occurred in Cuba in September 1933. It began as a revolt of sergeants and enlisted men in the military, who soon allied with student activists in the Directorio Estudiantil Universitario.', 1933, 9, 5, 1933, 9, 5, 'day', '5 September 1933', 30, 'https://en.wikipedia.org/wiki/Cuban_Revolution_of_1933'),
  ('Q8964623', '1952 Cuban coup d''état', 'The 1952 Cuban coup d''état took place in Cuba on March 10, 1952, when the Cuban Constitutional Army, led by Fulgencio Batista, intervened in the election that was scheduled to be held on 1 June 1952, staging a coup d''état and establishing a de facto military dictatorship in the country. The coup has been referred to as the Batistazo in Cuban political jargon.', 1952, 3, 10, NULL, NULL, NULL, 'day', '10 March 1952', 45, 'https://en.wikipedia.org/wiki/1952_Cuban_coup_d''%C3%A9tat'),
  ('Q11211553', 'Attack on the Moncada Barracks', 'The Moncada Barracks were military barracks in Santiago de Cuba, Cuba named after General Guillermo Moncada, a hero of the Cuban War of Independence. On 26 July 1953, the barracks was the site of an armed attack by a small group of revolutionaries led by Fidel Castro.', 1953, 7, 26, NULL, NULL, NULL, 'day', '26 July 1953', 45, 'https://en.wikipedia.org/wiki/Attack_on_the_Moncada_Barracks'),
  ('Q5778565', 'Battle of Alegría de Pío', 'The Battle of Alegría de Pío was a battle in Cuba fought between the 26th of July Movement and the Cuban National Army. It was the first battle fought between the Cuban rebels and the Cuban military during the Cuban Revolution following the landing of 82 members of the movement, headed by Fidel Castro, on the southern coast of Cuba 3 days prior.', 1956, 12, 5, NULL, NULL, NULL, 'day', '5 December 1956', 39, 'https://en.wikipedia.org/wiki/Battle_of_Alegr%C3%ADa_de_P%C3%ADo'),
  ('Q2153101', 'Battle of Santa Clara', 'The Battle of Santa Clara was a series of events in late December 1958 that led to the capture of the Cuban city of Santa Clara by rebel forces under the command of Che Guevara at the end of the Cuban Revolution. A decisive victory for the rebels who fought against the regime of General Fulgencio Batista, the battle culminated in the Triumph of the Revolution.', 1958, 12, 28, 1959, 1, 1, 'day', '28 December 1958 – 1 January 1959', 61, 'https://en.wikipedia.org/wiki/Battle_of_Santa_Clara'),
  ('Q3636292', 'Battle of La Plata', 'The Battle of La Plata (11-21 July 1958) was part of Operation Verano, the summer offensive of 1958 launched by the Batista government during the Cuban Revolution. The battle resulted from a complex plan created by Cuban General Cantillo to directly attack Castro''s mountain base in the Sierra Maestra.', 1958, 7, 21, NULL, NULL, NULL, 'day', '21 July 1958', 34, 'https://en.wikipedia.org/wiki/Battle_of_La_Plata'),
  ('Q3636494', 'Battle of Las Mercedes', 'The Battle of Las Mercedes (29 July – 8 August 1958) was the last battle which occurred during the course of Operation Verano, the summer offensive of 1958 launched by the Batista military dictatorship during the Cuban Revolution against the nationalist independence Cuban rebels of the 26th of July Movement. The battle was a trap, designed by Cuban General Eulogio Cantillo to lure Fidel Castro''s guerrillas into a place where they could be surrounded and destroyed.', 1958, 7, 29, 1958, 8, 8, 'day', '29 July 1958 – 8 August 1958', 37, 'https://en.wikipedia.org/wiki/Battle_of_Las_Mercedes'),
  ('Q3636666', 'Battle of Yaguajay', 'The Battle of Yaguajay (19 – 30 December 1958) was a decisive victory for the Cuban Revolutionaries over the soldiers of the Batista government near the city of Santa Clara in Cuba during the Cuban Revolution.', 1958, 12, 19, 1958, 12, 30, 'day', '19 December 1958 – 30 December 1958', 34, 'https://en.wikipedia.org/wiki/Battle_of_Yaguajay'),
  ('Q11264', 'Cuban Revolution', 'The Cuban Revolution (Spanish: Revolución cubana) was the military and political movement that overthrew the dictatorship of Fulgencio Batista, who had ruled Cuba from 1952 to 1959. The revolution began after the 1952 Cuban coup d''état, in which Batista overthrew the emerging Cuban democracy and consolidated power.', 1959, 1, 1, NULL, NULL, NULL, 'day', '1 January 1959', 85, 'https://en.wikipedia.org/wiki/Cuban_Revolution'),
  ('Q2507413', 'Escambray rebellion', 'The Escambray rebellion was an armed conflict from 1959 to 1965 in the Escambray Mountains during which several insurgent groups fought against the Cuban government led by Fidel Castro. The military operation against the rebellion was called the Struggle Against Bandits (Spanish: Lucha Contra Bandidos, or LCB) by the Cuban government.', 1959, NULL, NULL, 1965, NULL, NULL, 'year', '1959–1965', 53, 'https://en.wikipedia.org/wiki/Escambray_rebellion'),
  ('Q128160', 'Cuban Missile Crisis', 'The Cuban Missile Crisis, also known as the October Crisis in Cuba (Spanish: Crisis de Octubre), or the Caribbean Crisis (Russian: Карибский кризис, romanized: Karibskiy krizis), was a 13-day confrontation between the governments of the United States and the Soviet Union, when American deployments of nuclear missiles in the United Kingdom, Italy and Turkey were matched by Soviet deployments of nuclear missiles in Cuba. The crisis lasted from 16 to 28 October 1962.', 1962, NULL, NULL, 1962, 10, 28, 'year', '1962', 86, 'https://en.wikipedia.org/wiki/Cuban_Missile_Crisis'),
  ('Q1891008', 'Sand War', 'The Sand War (Arabic: حَرْبُ الرِّمَال, romanized: Ḥarb ar-Rimāl) was a border conflict between Algeria and Morocco fought from September 25 to October 30, 1963, although a formal peace treaty was not signed until February 20, 1964. It resulted largely from the Moroccan government''s claim to portions of Algeria''s Tindouf and Béchar provinces.', 1963, 9, 25, 1964, 2, 20, 'day', '25 September 1963 – 20 February 1964', 63, 'https://en.wikipedia.org/wiki/Sand_War'),
  ('Q322607', 'War of Attrition', 'The War of Attrition (Arabic: حرب الاستنزاف, romanized: Ḥarb al-Istinzāf; Hebrew: מלחמת ההתשה, romanized: Milḥemet haHatashah) involved fighting between Israel and Egypt, Jordan, the Palestine Liberation Organisation (PLO) and their allies from 1967 to 1970. Following the 1967 Six-Day War, no serious diplomatic efforts were made to resolve the issues at the heart of the Arab–Israeli conflict.', 1967, 7, 1, 1970, 8, 7, 'day', '1 July 1967 – 7 August 1970', 73, 'https://en.wikipedia.org/wiki/War_of_Attrition'),
  ('Q796498', 'Third Indochina War', 'The Third Indochina War was a series of interconnected military conflicts among the various communist factions over strategic influence in mainland Southeast Asia after communist victory in South Vietnam, Laos, and Cambodia in 1975. The conflict primarily started due to continued raids and incursions by the Khmer Rouge into Vietnamese territory that they sought to retake.', 1975, 5, 1, 1991, 10, 23, 'day', '1 May 1975 – 23 October 1991', 53, 'https://en.wikipedia.org/wiki/Third_Indochina_War'),
  ('Q12055176', 'Angolan Civil War', 'The Angolan Civil War (Portuguese: Guerra Civil Angolana) was a civil war in Angola, beginning in 1975 and continuing, with interludes, until 2002. The war began immediately after Angola became independent from Portugal in November 1975.', 1975, 11, 11, 2002, 4, 4, 'day', '11 November 1975 – 4 April 2002', 74, 'https://en.wikipedia.org/wiki/Angolan_Civil_War'),
  ('Q318250', 'Ogaden War', 'The Ogaden War, also known as the Ethio-Somali War (Somali: Dagaalkii Xoraynta Soomaali Galbeed, Amharic: የኢትዮጵያ ሶማሊያ ጦርነት, romanized: ye’ītiyop’iya somalīya t’orinet), was a military conflict between Somalia and Ethiopia fought from July 1977 to March 1978 over control of the sovereignty of the Ogaden region. Somalia launched an invasion in support of the Western Somali Liberation Front (WSLF) insurgency, triggering a broader inter-state war.', 1977, 7, 12, 1978, 3, 23, 'day', '12 July 1977 – 23 March 1978', 73, 'https://en.wikipedia.org/wiki/Ogaden_War'),
  ('Q2745406', 'Shaba II', 'Shaba II was a brief conflict fought in the Zairean province of Shaba (now Katanga) in 1978. The conflict broke out on 11 May 1978 after 6,500 rebels from the Congolese National Liberation Front (FNLC), a Katangese separatist militia, crossed the border from Angola into Zaire in an attempt to achieve the province''s secession from the Zairian regime of Mobutu Sese Seko.', 1978, 6, NULL, NULL, NULL, NULL, 'month', 'June 1978', 45, 'https://en.wikipedia.org/wiki/Shaba_II'),
  ('Q501866', '1983 Invasion of Grenada', 'The United States and a coalition of Caribbean countries invaded the island nation of Grenada at dawn on 25 October 1983. It was codenamed Operation Urgent Fury by the U.S. military, and resulted in military occupation within a few days.', 1983, 10, 25, 1983, 12, 15, 'day', '25 October 1983 – 15 December 1983', 71, 'https://en.wikipedia.org/wiki/United_States_invasion_of_Grenada'),
  ('Q7843235', 'Tripartite Accord', 'The Agreement among the People''s Republic of Angola, the Republic of Cuba, and the Republic of South Africa (also known as the Tripartite Accord, Three Powers Accord or New York Accords) granted independence to Namibia (then known as South West Africa) from South Africa and ended the direct involvement of foreign troops in the Angolan Civil War. The accords were signed on 22 December 1988 at the United Nations Headquarters in New York City by the Foreign Ministers of People''s Republic of Angola (Afonso Van-Dunem), Republic of Cuba (Isidoro Malmierca Peoli) and Republic of South Africa…', 1988, 12, 22, NULL, NULL, NULL, 'day', '22 December 1988', 34, 'https://en.wikipedia.org/wiki/Tripartite_Accord_(1988)'),
  ('Q5192135', 'Cubana de Aviación Flight 9646', 'Cubana de Aviación Flight 9046 was a chartered Ilyushin Il-62M airliner (registered CU-T1281) operated by Cubana, which crashed on 3 September 1989, shortly after takeoff from José Martí International Airport. Flight 9046 was due to operate a non-scheduled international Havana-Cologne-Milan passenger service.', 1989, 9, 3, NULL, NULL, NULL, 'day', '3 September 1989', 50, 'https://en.wikipedia.org/wiki/Cubana_de_Aviaci%C3%B3n_Flight_9046'),
  ('Q282999', 'Aero Caribbean Flight 883', 'Aero Caribbean Flight 883 was an international scheduled passenger service from Port-au-Prince, Haiti to Havana, Cuba with a stopover in Santiago de Cuba. On 4 November 2010, the ATR 72 operating the route crashed in the central Cuban province of Sancti Spíritus, killing all 61 passengers and 7 crew members aboard.', 2010, 11, 4, NULL, NULL, NULL, 'day', '4 November 2010', 57, 'https://en.wikipedia.org/wiki/Aero_Caribbean_Flight_883'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q107487626', '2021 Cuban protests', 'A series of protests against the Cuban government and the Communist Party of Cuba began on 11 July 2021, triggered by a shortage of food and medicine and the government''s response to the resurgent COVID-19 pandemic in Cuba. The protests were the largest anti-government demonstrations since the Maleconazo in 1994.', 2021, 7, 11, 2021, NULL, NULL, 'day', '2021', 61, 'https://en.wikipedia.org/wiki/2021_Cuban_protests'),
  ('Q111778863', '2022 Cuban referendum', 'A referendum was held on 25 September 2022 in Cuba to approve amendments to the Family Code of the Cuban Constitution. The revised code contains stronger rules on gender equality and modernizes protections for women, children, the elderly and people with disabilities.', 2022, 9, 25, NULL, NULL, NULL, 'day', '25 September 2022', 51, 'https://en.wikipedia.org/wiki/2022_Cuban_Family_Code_referendum'),
  ('Q131138871', '2024 Cuba earthquake', 'This is a list of earthquakes in 2024. Only earthquakes of magnitude 6 or above are included, unless they result in significant damage and/or casualties.', 2024, 11, 10, NULL, NULL, NULL, 'day', '10 November 2024', 34, 'https://en.wikipedia.org/wiki/2024_Cuba_earthquake'),
  ('Q138492180', '2026 Cuban boat incident', 'On 25 February 2026, an armed maritime confrontation occurred between a patrol vessel of the Cuban Border Guard Troops and a motor boat registered in the United States near Cayo Falcones, off the northern coast of Villa Clara Province, within Cuban territorial waters. Cuban authorities stated that the occupants of the motor boat opened fire after being intercepted, wounding the commanding officer of the patrol vessel.', 2026, 2, 25, NULL, NULL, NULL, 'day', '25 February 2026', 39, 'https://en.wikipedia.org/wiki/2026_Cuban_boat_incident');
